bool StyleEditor(UiStyle& s) {
    bool changed=ImGui::ColorEdit4("Text",s.Text.data());
    const char* labels[]={"Fill top left","Fill top right","Fill bottom right","Fill bottom left"};
    for (int i=0;i<4;++i) {changed=ImGui::ColorEdit4(labels[i],s.Fill[i].data())||changed;}
    if (ImGui::Button("Use top left as solid fill")) {s.Fill.fill(s.Fill[0]);changed=true;}
    changed=ImGui::DragFloat4("Corner radius",s.Radius.data(),.5f,0,4096)||changed;
    changed=ImGui::ColorEdit4("Border",s.Border.data())||changed;changed=ImGui::DragFloat("Border width",&s.BorderWidth,.25f,0,1024)||changed;
    changed=ImGui::ColorEdit4("Shadow",s.Shadow.data())||changed;changed=ImGui::DragFloat("Shadow X",&s.ShadowX,.5f,-1024,1024)||changed;changed=ImGui::DragFloat("Shadow Y",&s.ShadowY,.5f,-1024,1024)||changed;changed=ImGui::DragFloat("Shadow blur",&s.ShadowBlur,.5f,0,128)||changed;changed=ImGui::SliderFloat("Opacity",&s.Opacity,0,1)||changed;return changed;
}
template<class T> bool InheritToggle(const char* label,std::optional<T>& value,const T& fallback) {bool override=value.has_value();if (!ImGui::Checkbox(label,&override)) {return false;}if (override) {value=fallback;}else {value.reset();}return true;}
bool RunEditor(UiTextRun& run,const UiElement& e,const std::vector<UiFont>& fonts) {
    bool changed=ImGui::InputTextMultiline("Run text",&run.Text);changed=InheritToggle("Override color",run.Color,e.Normal.Text)||changed;if (run.Color) {changed=ImGui::ColorEdit4("Run color",run.Color->data())||changed;}
    changed=InheritToggle("Override size",run.Size,e.Typography.Size)||changed;if (run.Size) {changed=ImGui::DragFloat("Run size",&*run.Size,.5f,1,256)||changed;}
    changed=InheritToggle("Override weight",run.Weight,e.Typography.Weight)||changed;if (run.Weight) {changed=ImGui::SliderInt("Run weight",&*run.Weight,100,900)||changed;}
    changed=InheritToggle("Override tracking",run.LetterSpacing,e.Typography.LetterSpacing)||changed;if (run.LetterSpacing) {changed=ImGui::DragFloat("Run tracking",&*run.LetterSpacing,.1f,-32,128)||changed;}
    changed=InheritToggle("Override italic",run.Italic,e.Typography.Italic)||changed;if (run.Italic) {changed=ImGui::Checkbox("Run italic",&*run.Italic)||changed;}
    changed=InheritToggle("Override underline",run.Underline,e.Typography.Underline)||changed;if (run.Underline) {changed=ImGui::Checkbox("Run underline",&*run.Underline)||changed;}
    changed=InheritToggle("Override strike",run.StrikeThrough,e.Typography.StrikeThrough)||changed;if (run.StrikeThrough) {changed=ImGui::Checkbox("Run strike",&*run.StrikeThrough)||changed;}
    bool fontOverride=run.Family.has_value()||run.FontFile.has_value();if (ImGui::Checkbox("Override font",&fontOverride)) {if (fontOverride) {run.Family=e.Typography.Family;run.FontFile=e.Typography.FontFile;}else {run.Family.reset();run.FontFile.reset();}changed=true;}
    if (fontOverride) {const auto current=run.Family.value_or(e.Typography.Family);if (ImGui::BeginCombo("Run font",current.empty() ? "OS default":current.c_str())) {if (ImGui::Selectable("OS default",current.empty())) {run.Family="";run.FontFile=std::filesystem::path{};changed=true;}for (std::size_t i=0;i<fonts.size();++i) {ImGui::PushID(static_cast<int>(i));if (ImGui::Selectable((fonts[i].Family+(fonts[i].File.empty() ? "":" (Font folder)")).c_str())) {run.Family=fonts[i].Family;run.FontFile=fonts[i].File;changed=true;}ImGui::PopID();}ImGui::EndCombo();}}
    return changed;
}
